package org.securemail.worker;
import org.securemail.community.agent.PublicSourceHttp;
import org.securemail.community.agent.SourceParser;
import org.securemail.community.agent.RobotsPolicy;

import org.junit.jupiter.api.Test;
import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;
import static org.junit.jupiter.api.Assertions.*;

final class SourceSecurityTest {
 @Test void rejectsPrivateSpecialIpv4AndIpv6Ranges()throws Exception{for(String ip:List.of("127.0.0.1","0.0.0.0","10.0.0.1","100.64.0.1","169.254.169.254","172.16.0.1","192.168.1.1","192.0.2.1","198.18.0.1","198.51.100.1","203.0.113.1","224.0.0.1","::1","fe80::1","fc00::1","2001:db8::1","2002:0808:0808::1","2001::1","2001:2::1","2001:3::1","2001:100::1","3fff::1"))assertFalse(PublicSourceHttp.publicAddress(InetAddress.getByName(ip)),ip);assertTrue(PublicSourceHttp.publicAddress(InetAddress.getByName("8.8.8.8")));assertTrue(PublicSourceHttp.publicAddress(InetAddress.getByName("2606:4700:4700::1111")));}
 @Test void rejectsProtocolsCredentialsIpLiteralsAndNonallowlistedRedirects(){for(String url:List.of("http://news.example/","file:///etc/passwd","https://user:pass@news.example/","https://127.0.0.1/","https://news.example:8080/","https://evil.example/","https://news.example/a#x"))assertThrows(IOException.class,()->PublicSourceHttp.validate(URI.create(url),Set.of("news.example")));}
 @Test void dnsIsPinnedAndRebindingCannotReachPrivateTarget()throws Exception{AtomicInteger dns=new AtomicInteger(),sockets=new AtomicInteger();var http=new PublicSourceHttp(h->new InetAddress[]{InetAddress.getByName(dns.getAndIncrement()==0?"8.8.8.8":"127.0.0.1")},(uri,ip,max)->{sockets.incrementAndGet();assertEquals("8.8.8.8",ip.getHostAddress());return new PublicSourceHttp.Response(200,Map.of(),new byte[0],uri);});http.get(URI.create("https://news.example/rss"),Set.of("news.example"),100);assertThrows(IOException.class,()->http.get(URI.create("https://news.example/rss"),Set.of("news.example"),100));assertEquals(1,sockets.get());}
 @Test void mixedDnsAnswerOrRedirectCannotReachMetadataService()throws Exception{AtomicInteger sockets=new AtomicInteger();var mixed=new PublicSourceHttp(h->new InetAddress[]{InetAddress.getByName("8.8.8.8"),InetAddress.getByName("169.254.169.254")},(u,i,m)->{sockets.incrementAndGet();return null;});assertThrows(IOException.class,()->mixed.get(URI.create("https://news.example/"),Set.of("news.example"),100));assertEquals(0,sockets.get());var redirect=new PublicSourceHttp(h->new InetAddress[]{InetAddress.getByName("8.8.8.8")},(u,i,m)->new PublicSourceHttp.Response(302,Map.of("location","http://169.254.169.254/latest/meta-data"),new byte[0],u));assertThrows(IOException.class,()->redirect.get(URI.create("https://news.example/"),Set.of("news.example"),100));}
 @Test void boundedHttpRejectsSmugglingAndCompressedBombs(){for(String response:List.of("HTTP/1.1 200 OK\r\nContent-Length: 2\r\nContent-Length: 3\r\n\r\nabc","HTTP/1.1 200 OK\r\nContent-Length: 5\r\nTransfer-Encoding: chunked\r\n\r\n0\r\n\r\n","HTTP/1.1 200 OK\r\nContent-Encoding: gzip\r\n\r\nabc","HTTP/1.1 200 OK\r\nContent-Length: 5000\r\n\r\n"))assertThrows(IOException.class,()->PublicSourceHttp.readResponse(new ByteArrayInputStream(response.getBytes(StandardCharsets.US_ASCII)),URI.create("https://news.example/"),100));}
 @Test void boundedChunkedHttpParsesRealWireFormat()throws Exception{String response="HTTP/1.1 200 OK\r\nTransfer-Encoding: chunked\r\nContent-Type: text/plain\r\n\r\n3\r\nabc\r\n2\r\nde\r\n0\r\n\r\n";assertArrayEquals("abcde".getBytes(StandardCharsets.US_ASCII),PublicSourceHttp.readResponse(new ByteArrayInputStream(response.getBytes(StandardCharsets.US_ASCII)),URI.create("https://news.example/"),100).body());}
 @Test void rssAndAtomAreParsedWithoutFetchingArticleLinks()throws Exception{String rss="<rss><channel><item><title>Новость</title><link>https://news.example/a</link><pubDate>Thu, 15 Oct 2026 12:00:00 GMT</pubDate><description><![CDATA[<p>Факт</p><script>steal()</script>]]></description></item></channel></rss>";var parser=new SourceParser();var items=parser.parse("source","owner",true,"ru/ru-mow/moscow",URI.create("https://news.example/rss"),"application/rss+xml",rss.getBytes(StandardCharsets.UTF_8));assertEquals(1,items.size());assertEquals("Факт",items.get(0).text());assertEquals("2026-10-15T12:00:00Z",items.get(0).publishedAt());String atom="<feed xmlns=\"http://www.w3.org/2005/Atom\"><entry><title>Событие</title><link href=\"https://news.example/b\"/><updated>2026-10-15T12:00:00Z</updated><summary>Описание</summary></entry></feed>";assertEquals("https://news.example/b",parser.parse("s","g",false,"ru/ru-mow/moscow",URI.create("https://news.example/atom"),"application/atom+xml",atom.getBytes(StandardCharsets.UTF_8)).get(0).url());}
 @Test void xmlExternalEntityAndExpansionBombRejected(){for(String xml:List.of("<!DOCTYPE rss [<!ENTITY x SYSTEM 'file:///etc/passwd'>]><rss><item><title>&x;</title></item></rss>","<!DOCTYPE rss [<!ENTITY a 'aaa'><!ENTITY b '&a;&a;&a;'>]><rss>&b;</rss>"))assertThrows(IOException.class,()->new SourceParser().parse("s","g",false,"ru/ru-mow/moscow",URI.create("https://news.example/"),"application/xml",xml.getBytes(StandardCharsets.UTF_8)));}
 @Test void htmlNeverExecutesScriptAndDangerousLinksAreDiscarded()throws Exception{String html="<html><head><title>Муниципальная новость</title><meta name='date' content='2026-10-15T12:00:00Z'></head><body><h1>Открытие</h1><script>runCommand()</script><style>hidden</style><p>Описание события</p></body></html>";var result=new SourceParser().parse("s","g",true,"ru/ru-mow/moscow",URI.create("https://news.example/a"),"text/html; charset=UTF-8",html.getBytes(StandardCharsets.UTF_8));assertEquals(1,result.size());assertFalse(result.get(0).text().contains("runCommand"));assertFalse(SourceParser.safeMetadataUrl(URI.create("javascript:alert(1)")));assertFalse(SourceParser.safeMetadataUrl(URI.create("file:///etc/passwd")));}
 @Test void robotRulesAndMaliciousRegexAreDataOnly(){assertFalse(RobotsPolicy.allows("User-agent: *\nDisallow: /private\n","/private/a"));assertTrue(RobotsPolicy.allows("User-agent: *\nDisallow: /private\n","/news"));assertFalse(RobotsPolicy.allows("User-agent: AEGIS-News\nDisallow: /*secret$","/a/secret"));assertTrue(RobotsPolicy.allows("User-agent: *\nDisallow: /(a+)+$","/"+"a".repeat(1000)));assertFalse(RobotsPolicy.allows("User-agent: *\nCrawl-delay: 3600","/news"));}
 @Test void sourceSizeAndFeedEntryCountAreBounded(){assertThrows(IOException.class,()->new SourceParser().parse("s","g",false,"ru/ru-mow/moscow",URI.create("https://news.example/"),"text/html",new byte[1000001]));String feed="<rss><channel>"+"<item><title>a</title><description>b</description><link>https://news.example/x</link></item>".repeat(101)+"</channel></rss>";assertThrows(IOException.class,()->new SourceParser().parse("s","g",false,"ru/ru-mow/moscow",URI.create("https://news.example/"),"application/xml",feed.getBytes(StandardCharsets.UTF_8)));}
}
